catalog_script_client.script:
function onLoad() {
    //debugger;

    var emp = g_form.getValue('subject_person');
    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMTelWrkUtils');
    ga.addParam('sysparm_name', 'getTeleWorkInfo');
    ga.addParam('sysparm_employee_sys_id', emp);
    ga.getXMLAnswer(resultTeleworkInfo);

    // GlideAjax callback function
    function resultTeleworkInfo(answer) {
        var resultsObj = JSON.parse(answer);

        g_form.setValue("designated_workplace_address", resultsObj.workplaceAddressId, resultsObj.workplaceAddressName);
        g_form.setValue("type_telework_arrangement", resultsObj.teleworkType);
        if (resultsObj.teleworkType === "telework_flexible") {
            switch (resultsObj.flexibleDays.toString()) { // take care of old values from old TAs
                case "days_12":
                    g_form.setValue("flexible_telework_choices", "days_1");
                    break;
                case "days_23":
                    g_form.setValue("flexible_telework_choices", "days_2");
                    break;
                case "days_34":
                    g_form.setValue("flexible_telework_choices", "days_3");
                    break;
                case "days_45":
                    g_form.setValue("flexible_telework_choices", "days_4");
                    break;
                default:
                    g_form.setValue("flexible_telework_choices", resultsObj.flexibleDays);
                    break;
            }
            if (resultsObj.flexibleOther !== "") {
                g_form.setValue("specify_number_telework_days", resultsObj.flexibleOther);
            }
        } else {
            g_form.setValue("fixed_telework_choices", resultsObj.fixedDays);
            g_form.setValue("telework_monday", resultsObj.fixedMonday);
            g_form.setValue("telework_tuesday", resultsObj.fixedTuesday);
            g_form.setValue("telework_wednesday", resultsObj.fixedWednesday);
            g_form.setValue("telework_thursday", resultsObj.fixedThursday);
            g_form.setValue("telework_friday", resultsObj.fixedFriday);
        }
        g_form.setValue("telework_location_address", resultsObj.teleworkAddress);
        g_form.setValue("telework_telephone_number", resultsObj.teleworkPhone);
        g_form.setValue("emergency_contact_name", resultsObj.emergencyContact);
        g_form.setValue("relationship_to_employee", resultsObj.emergencyRelationship);
        g_form.setValue("emergency_contact_telephone", resultsObj.emergencyPhone);
    }

}
